function demo() {
  if (true) {
    var hoisted = "function scoped";
    let blocked = "block scoped";
  }
  console.log(hoisted); // "function scoped"
  // console.log(blocked); // ReferenceError
}
demo();

const secret = "global";

function makeReader() {
  const secret = "closure";
  return function read() {
    return secret;
  };
}

const read = makeReader();
console.log(read()); // "closure" — not "global"

let color = "blue";

function paint() {
  let color = "red";
  function stroke() {
    console.log(color); // "red" — nearest binding wins
  }
  stroke();
}
paint();
